+					   "for protocol \"%s\" (pattern=\"%s\"): %s",
+					   proto->name ? proto->name : "(unnamed)",
+					   (const char *)proto_def->path,
+					   errmsg ? errmsg : "unknown error");
+				g_free(errmsg);
 			}
 		}
 	}

